DO $$ BEGIN CREATE TYPE tesoreria.dues_agreement_kind AS ENUM ('SIMPLE', 'INSTALLMENT'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE tesoreria.dues_agreement_status AS ENUM ('ACTIVE', 'FULFILLED', 'CANCELLED', 'SUPERSEDED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS tesoreria.dues_agreements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), socio_id uuid NOT NULL REFERENCES socios.socios(id) ON DELETE RESTRICT, obligation_id uuid NOT NULL REFERENCES tesoreria.dues_obligations(id) ON DELETE RESTRICT, kind tesoreria.dues_agreement_kind NOT NULL, status tesoreria.dues_agreement_status NOT NULL DEFAULT 'ACTIVE', revision_number integer NOT NULL DEFAULT 1, terms jsonb NOT NULL, reason text NOT NULL, revision_of_agreement_id uuid REFERENCES tesoreria.dues_agreements(id) ON DELETE RESTRICT, revision_reason text, operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, authorization_evidence jsonb NOT NULL DEFAULT '{}', caller_key text NOT NULL, request_fingerprint char(64) NOT NULL, agreement_date date NOT NULL DEFAULT CURRENT_DATE, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT dues_agreements_reason_check CHECK (btrim(reason) <> ''), CONSTRAINT dues_agreements_revision_number_check CHECK (revision_number > 0), CONSTRAINT dues_agreements_revision_check CHECK ((revision_of_agreement_id IS NULL AND revision_reason IS NULL AND revision_number = 1) OR (revision_of_agreement_id IS NOT NULL AND revision_reason IS NOT NULL AND btrim(revision_reason) <> '' AND revision_number > 1)), CONSTRAINT dues_agreements_fingerprint_check CHECK (length(btrim(request_fingerprint)) = 64), CONSTRAINT dues_agreements_operator_caller_key_unique UNIQUE (operator_id, caller_key));
ALTER TABLE tesoreria.dues_agreements ADD COLUMN IF NOT EXISTS obligation_id uuid REFERENCES tesoreria.dues_obligations(id) ON DELETE RESTRICT;
ALTER TABLE tesoreria.dues_agreements ADD COLUMN IF NOT EXISTS agreement_date date NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE tesoreria.dues_agreements ADD COLUMN IF NOT EXISTS revision_number integer NOT NULL DEFAULT 1;
ALTER TABLE tesoreria.dues_agreements ALTER COLUMN obligation_id SET NOT NULL;
DO $$ BEGIN ALTER TABLE tesoreria.dues_agreements ADD CONSTRAINT dues_agreements_revision_number_check CHECK (revision_number > 0); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE UNIQUE INDEX IF NOT EXISTS dues_agreements_active_obligation_unique ON tesoreria.dues_agreements (obligation_id) WHERE status = 'ACTIVE';
CREATE TABLE IF NOT EXISTS tesoreria.dues_community_work (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), socio_id uuid NOT NULL REFERENCES socios.socios(id) ON DELETE RESTRICT, obligation_id uuid NOT NULL REFERENCES tesoreria.dues_obligations(id) ON DELETE RESTRICT, settlement_id uuid NOT NULL UNIQUE REFERENCES tesoreria.dues_settlements(id) ON DELETE RESTRICT, amount numeric(14,2) NOT NULL, evidence jsonb NOT NULL, approval_reason text NOT NULL, operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, authorization_evidence jsonb NOT NULL DEFAULT '{}', caller_key text NOT NULL, request_fingerprint char(64) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT dues_community_work_amount_check CHECK (amount > 0), CONSTRAINT dues_community_work_reason_check CHECK (btrim(approval_reason) <> ''), CONSTRAINT dues_community_work_fingerprint_check CHECK (length(btrim(request_fingerprint)) = 64));
CREATE OR REPLACE FUNCTION tesoreria.validate_dues_agreement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE obligation_socio uuid; obligation_amount numeric; outstanding numeric; parent_obligation uuid; parent_revision_number integer; installment jsonb; agreed_cents bigint; installment_cents bigint; installment_sum bigint := 0; previous_due_date date; due_date date; BEGIN IF jsonb_typeof(NEW.terms) IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.terms->'installments') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.terms->'installments') NOT BETWEEN 1 AND 60 OR (NEW.terms->>'amountCents') IS NULL OR (NEW.terms->>'amountCents') !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'agreement terms are outside the approved bounds' USING ERRCODE='23514', CONSTRAINT='dues_agreements_terms_check'; END IF; agreed_cents := (NEW.terms->>'amountCents')::bigint; IF agreed_cents > 99999999999999 THEN RAISE EXCEPTION 'agreement amount exceeds supported money range' USING ERRCODE='23514', CONSTRAINT='dues_agreements_terms_check'; END IF; FOR installment IN SELECT value FROM jsonb_array_elements(NEW.terms->'installments') LOOP IF jsonb_typeof(installment) IS DISTINCT FROM 'object' OR (installment->>'amountCents') IS NULL OR (installment->>'amountCents') !~ '^[1-9][0-9]*$' OR (installment->>'dueDate') IS NULL OR (installment->>'dueDate') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'agreement installment is invalid' USING ERRCODE='23514', CONSTRAINT='dues_agreements_terms_check'; END IF; installment_cents := (installment->>'amountCents')::bigint; due_date := (installment->>'dueDate')::date; IF due_date::text <> installment->>'dueDate' OR due_date < NEW.agreement_date OR (previous_due_date IS NOT NULL AND due_date <= previous_due_date) THEN RAISE EXCEPTION 'agreement installment dates must be valid, ordered, and on or after the agreement date' USING ERRCODE='23514', CONSTRAINT='dues_agreements_terms_check'; END IF; installment_sum := installment_sum + installment_cents; previous_due_date := due_date; END LOOP; IF installment_sum <> agreed_cents THEN RAISE EXCEPTION 'agreement installments must sum to the agreed amount' USING ERRCODE='23514', CONSTRAINT='dues_agreements_terms_check'; END IF; SELECT socio_id, amount INTO obligation_socio, obligation_amount FROM tesoreria.dues_obligations WHERE id = NEW.obligation_id FOR UPDATE; IF obligation_socio IS NULL OR obligation_socio IS DISTINCT FROM NEW.socio_id THEN RAISE EXCEPTION 'agreement obligation does not belong to the socio' USING ERRCODE='23514', CONSTRAINT='dues_agreements_obligation_owner_check'; END IF; SELECT obligation_amount - COALESCE(SUM(CASE WHEN kind = 'ALLOCATION' THEN amount ELSE -amount END), 0) INTO outstanding FROM tesoreria.dues_allocations WHERE obligation_id = NEW.obligation_id; IF agreed_cents > (COALESCE(outstanding, obligation_amount) * 100)::bigint THEN RAISE EXCEPTION 'agreement amount exceeds outstanding obligation debt' USING ERRCODE='23514', CONSTRAINT='dues_agreements_outstanding_check'; END IF; IF NEW.revision_of_agreement_id IS NULL THEN IF NEW.revision_number <> 1 THEN RAISE EXCEPTION 'root agreement must have revision number 1' USING ERRCODE='23514', CONSTRAINT='dues_agreements_revision_number_check'; END IF; ELSE SELECT obligation_id, revision_number INTO parent_obligation, parent_revision_number FROM tesoreria.dues_agreements WHERE id = NEW.revision_of_agreement_id; IF parent_obligation IS DISTINCT FROM NEW.obligation_id OR NEW.revision_number <> parent_revision_number + 1 THEN RAISE EXCEPTION 'agreement revision must preserve obligation identity and increment revision number' USING ERRCODE='23514', CONSTRAINT='dues_agreements_revision_obligation_check'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS dues_agreements_validate ON tesoreria.dues_agreements;
CREATE TRIGGER dues_agreements_validate BEFORE INSERT ON tesoreria.dues_agreements FOR EACH ROW EXECUTE FUNCTION tesoreria.validate_dues_agreement();
CREATE OR REPLACE FUNCTION tesoreria.validate_dues_community_work() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE settlement_socio uuid; settlement_kind tesoreria.dues_settlement_kind; settlement_amount numeric; obligation_socio uuid; BEGIN SELECT socio_id,kind,amount INTO settlement_socio,settlement_kind,settlement_amount FROM tesoreria.dues_settlements WHERE id=NEW.settlement_id; SELECT socio_id INTO obligation_socio FROM tesoreria.dues_obligations WHERE id=NEW.obligation_id; IF settlement_kind IS DISTINCT FROM 'NON_CASH' OR settlement_socio IS DISTINCT FROM NEW.socio_id OR obligation_socio IS DISTINCT FROM NEW.socio_id OR settlement_amount IS DISTINCT FROM NEW.amount THEN RAISE EXCEPTION 'community work must reference a matching non-cash settlement and obligation' USING ERRCODE='23514', CONSTRAINT='dues_community_work_settlement_check'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS dues_community_work_validate ON tesoreria.dues_community_work;
CREATE TRIGGER dues_community_work_validate BEFORE INSERT ON tesoreria.dues_community_work FOR EACH ROW EXECUTE FUNCTION tesoreria.validate_dues_community_work();
CREATE OR REPLACE FUNCTION tesoreria.verify_dues_agreement_supersession() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE successor_count integer; successor_status tesoreria.dues_agreement_status; successor_socio uuid; successor_obligation uuid; successor_revision integer; BEGIN IF OLD.status IS DISTINCT FROM 'ACTIVE' OR NEW.status IS DISTINCT FROM 'SUPERSEDED' THEN RETURN NULL; END IF; SELECT count(*)::int INTO successor_count FROM tesoreria.dues_agreements WHERE revision_of_agreement_id = NEW.id; IF successor_count <> 1 THEN RAISE EXCEPTION 'ACTIVE agreement supersession requires exactly one valid successor in the same transaction' USING ERRCODE='23514', CONSTRAINT='dues_agreements_supersession_check'; END IF; SELECT status, socio_id, obligation_id, revision_number INTO successor_status, successor_socio, successor_obligation, successor_revision FROM tesoreria.dues_agreements WHERE revision_of_agreement_id = NEW.id; IF successor_status IS DISTINCT FROM 'ACTIVE' OR successor_socio IS DISTINCT FROM NEW.socio_id OR successor_obligation IS DISTINCT FROM NEW.obligation_id OR successor_revision <> NEW.revision_number + 1 THEN RAISE EXCEPTION 'ACTIVE agreement supersession successor does not preserve active status, identity, or revision order' USING ERRCODE='23514', CONSTRAINT='dues_agreements_supersession_check'; END IF; RETURN NULL; END $$;
DROP TRIGGER IF EXISTS dues_agreements_supersession_atomic ON tesoreria.dues_agreements;
CREATE CONSTRAINT TRIGGER dues_agreements_supersession_atomic AFTER UPDATE OF status ON tesoreria.dues_agreements DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION tesoreria.verify_dues_agreement_supersession();
CREATE OR REPLACE FUNCTION tesoreria.reject_dues_agreement_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME = 'dues_agreements' AND OLD.status = 'ACTIVE' AND NEW.status = 'SUPERSEDED' AND OLD.socio_id IS NOT DISTINCT FROM NEW.socio_id AND OLD.obligation_id IS NOT DISTINCT FROM NEW.obligation_id AND OLD.kind IS NOT DISTINCT FROM NEW.kind AND OLD.revision_number IS NOT DISTINCT FROM NEW.revision_number AND OLD.terms IS NOT DISTINCT FROM NEW.terms AND OLD.reason IS NOT DISTINCT FROM NEW.reason AND OLD.revision_of_agreement_id IS NOT DISTINCT FROM NEW.revision_of_agreement_id AND OLD.revision_reason IS NOT DISTINCT FROM NEW.revision_reason AND OLD.operator_id IS NOT DISTINCT FROM NEW.operator_id AND OLD.authorization_evidence IS NOT DISTINCT FROM NEW.authorization_evidence AND OLD.caller_key IS NOT DISTINCT FROM NEW.caller_key AND OLD.request_fingerprint IS NOT DISTINCT FROM NEW.request_fingerprint AND OLD.agreement_date IS NOT DISTINCT FROM NEW.agreement_date AND OLD.created_at IS NOT DISTINCT FROM NEW.created_at THEN RETURN NEW; END IF; RAISE EXCEPTION 'dues agreements and community work are immutable' USING ERRCODE='55000'; END $$;
DROP TRIGGER IF EXISTS dues_agreements_immutable ON tesoreria.dues_agreements;
CREATE TRIGGER dues_agreements_immutable BEFORE UPDATE OR DELETE ON tesoreria.dues_agreements FOR EACH ROW EXECUTE FUNCTION tesoreria.reject_dues_agreement_mutation();
DROP TRIGGER IF EXISTS dues_community_work_immutable ON tesoreria.dues_community_work;
CREATE TRIGGER dues_community_work_immutable BEFORE UPDATE OR DELETE ON tesoreria.dues_community_work FOR EACH ROW EXECUTE FUNCTION tesoreria.reject_dues_agreement_mutation();
